-- Shoulder Cam (ShoulderCam.lua, ShoulderCalibrate.lua, ProfileChoices.lua): public since 2026-11-15
L["The Shoulder Cam uses one of Blizzard's experimental camera settings. The game would warn about it every time you log in, so Cinematic keeps that warning away while the Shoulder Cam is on. If the camera ever acts up, turn the Shoulder Cam off and your own camera settings come back."] = "肩部镜头使用了暴雪的一项实验性镜头设置。游戏每次登录都会对此发出警告，所以肩部镜头开启时 Cinematic 会挡住这条警告。如果镜头出了问题，关闭肩部镜头，你自己的镜头设置就会恢复。"
L["Accept"] = "接受"
L["Shoulder Cam is paused while the gamepad UI is on: the game keeps your character centered in it."] = "游戏手柄界面开启时肩部镜头会暂停：游戏会让你的角色保持在画面中央。"
L["Swap shoulders (Shoulder Cam)"] = "切换肩膀（肩部镜头）"
L["Where the camera sits, when it turns, and when it steps back behind you."] = "镜头的位置、何时转动、何时退回你身后。"
L["Follow HUD"] = "跟随 HUD"
L["Calibrate"] = "校准"
L["Measure where you sit for your race, sex and form, and share it."] = "测量你的种族、性别和形态在画面中的位置，并分享出来。"
L["Spot on screen"] = "画面位置"
L["Swap takes"] = "切换耗时"
L["Back from targeting yourself"] = "选中自己后的返回"
L["Off and on again takes"] = "关闭再开启耗时"
L["Turn to NPCs you talk to"] = "转向与你交谈的 NPC"
L["Turn to enemy"] = "转向敌人"
L["Enemy turn takes"] = "转向敌人耗时"
L["NPC turn takes"] = "转向 NPC 耗时"
L["How long the turn toward who you talk to takes as the window opens."] = "窗口打开时转向交谈对象所需的时间。"
L["NPC turn back takes"] = "从 NPC 转回耗时"
L["Frames follow the turn"] = "框体跟随转向"
L["Swing timers"] = "挥击计时条"
L["Cooldowns: essential"] = "冷却：核心"
L["Cooldowns: utility"] = "冷却：辅助"
L["Tracked buffs: icons"] = "追踪增益：图标"
L["Tracked buffs: bars"] = "追踪增益：计量条"
L["Spell alerts"] = "法术警报"
L["Height (all)"] = "高度（全部）"
L["Transition"] = "过渡"
L["Allow the Shoulder Cam"] = "允许肩部镜头"
L["Keeps the camera over your shoulder while this camera plays."] = "此镜头播放期间让镜头保持在你肩膀上方。"
L["Your Hearthstone and teleports."] = "你的炉石和传送。"
L["While you're dead, until you release."] = "你死亡期间，直到你释放灵魂。"
L["Walk camera"] = "行走镜头"
L["While you talk to a quest giver."] = "你与任务发布者交谈时。"
L["Your own cameras"] = "你自己的镜头"
L["Your scripts and shots, and cameras started from the camera wheel or a key."] = "你的脚本和镜头片段，以及从镜头轮盘或按键启动的镜头。"
L["Not supported at the moment"] = "暂不支持"
L["The Shoulder Cam doesn't work with the gamepad UI yet. While it's on, the game keeps your character in the middle of the screen, so the Shoulder Cam waits behind you and comes back by itself when you turn the gamepad UI off (Options > Gamepad (Beta) > Enable Gamepad UI)."] = "肩部镜头暂不支持游戏手柄界面。开启时游戏会让你的角色保持在画面中央，所以肩部镜头会在你身后等待，关闭游戏手柄界面后自动回来（选项 > 游戏手柄（测试版）> 启用游戏手柄界面）。"
L["Calibrating my camera, please ignore this line for a moment: I'm measuring where my character sits on the screen as the camera moves over my shoulder. Thanks for your patience!"] = "我在校准镜头，请暂时忽略这句话：我在测量镜头移到肩膀上方时我的角色在画面中的位置。谢谢耐心等待！"
L["On foot"] = "步行"
L["Form %s"] = "形态 %s"
L["Calibration stopped"] = "校准已停止"
L["Calibration: not enough readings"] = "校准：读数不足"
L["Try again somewhere open and flat."] = "请到开阔平坦的地方再试一次。"
L["Saved, and in use now. Share it from the Calibrate tab."] = "已保存，现在正在使用。可以在“校准”标签页分享。"
L["The readings disagree (%.2f apart): try again somewhere open and flat."] = "读数不一致（相差 %.2f）：请到开阔平坦的地方再试一次。"
L["Calibrating: step %d of %d"] = "校准中：第 %d 步，共 %d 步"
L["Stand still and leave the camera alone."] = "站着别动，不要碰镜头。"
L["Say it again and go on"] = "再说一次并继续"
L["The bubble's gone: click the button below to go on."] = "气泡消失了：点击下面的按钮继续。"
L["A fight started."] = "战斗开始了。"
L["You picked a target: clear it (Esc) and start again."] = "你选中了目标：清除它（Esc）后重新开始。"
L["It's already running."] = "已经在运行了。"
L["Clear your target first (Esc)."] = "请先清除目标（Esc）。"
L["This client can't read chat bubbles."] = "此客户端无法读取聊天气泡。"
L["Not in a dungeon, raid or battleground."] = "不能在地下城、团队副本或战场中进行。"
L["Stopped."] = "已停止。"
L["Calibrate the Shoulder Cam for %s?\n\nIt says a line in /say a few times (everyone near you sees it), so somewhere quiet is best. Stand still on open, flat ground and leave the camera alone for about 10 seconds."] = "为 %s 校准肩部镜头？\n\n它会用 /说 说几次一句话（附近的人都能看到），所以最好找个安静的地方。站在开阔平坦的地面上不动，大约 10 秒内不要碰镜头。"
L["Yes"] = "是"
L["No"] = "否"
L["Your Shoulder Cam measurements"] = "你的肩部镜头测量"
L["Your measurements on one line: copy it and paste it to us on Discord or GitHub."] = "一行显示的测量数据：复制后贴到 Discord 或 GitHub 给我们。"
L["Your measurements"] = "你的测量"
L["Character"] = "角色"
L["Form"] = "形态"
L["Date"] = "日期"
L["None yet: calibrate to add one."] = "还没有：校准以添加一条。"
L["You now: |cffffffff%s|r, size |cffffffff%.2f|r |cff9d9d9d(%s)|r"] = "你现在：|cffffffff%s|r，大小 |cffffffff%.2f|r |cff9d9d9d(%s)|r"
L["Good"] = "良好"
L["Not used"] = "未使用"
L["Cinema, over your shoulder. The camera sits over your shoulder with you to one side of the screen, and your resources, cast bar and Cooldown Manager sit under you and slide along with you. Fights bring up your personal resource display instead of your portrait. Everything else is Cinema's: as little UI as possible, every camera, Vision and all the atmosphere."] = "Cinema，越过你的肩膀。镜头位于你的肩膀上方，你在画面一侧，你的资源、施法条和冷却管理器在你下方随你滑动。战斗时显示个人资源显示而不是你的头像。其余都和 Cinema 一样：尽可能少的界面、所有镜头、视觉效果和全部氛围。"

