L["It uses one of Blizzard's experimental camera settings: picking it or its test agrees to that. Turn the Shoulder Cam off and your own camera settings come back."] = "它使用了暴雪的一项实验性镜头设置：选择或试用它即表示同意。关闭肩部镜头，你自己的镜头设置就会恢复。"
L["The camera moves over your shoulder, with you to one side of the screen. This glides in, swaps shoulders once and glides back. It uses one of Blizzard's experimental camera settings: trying it agrees to that, and your own camera settings come back after."] = "镜头移到你的肩膀上方，你在画面一侧。它会滑入、换一次肩膀，然后滑回。它使用了暴雪的一项实验性镜头设置：试用即表示同意，之后你自己的镜头设置会恢复。"
L["Over your shoulder outdoors, off your mount and out of dungeons and raids."] = "在户外、不骑坐骑、不在地下城和团队副本中时位于你的肩膀上方。"

