L["The camera sways a little from side to side."] = "镜头轻微左右摇摆。"
L["How much lower the camera sways, to look out across the water."] = "镜头摇摆时降低多少，以眺望水面。"
L["When you die, the camera slowly circles your body until you release or are revived."] = "你死亡时，镜头缓缓环绕你的尸体，直到你释放灵魂或被复活。"
L["If you die in a boss fight, the death camera waits for it to end."] = "如果你在首领战中死亡，死亡镜头会等战斗结束。"
L["No death camera when you can come back yourself, like with a soulstone."] = "可以自行复活时（如有灵魂石）不使用死亡镜头。"
L["Adds a button under the release popup to get your own view back."] = "在释放灵魂弹窗下方添加一个按钮，用于恢复你自己的视角。"
L["How far the camera pulls back while you're dead."] = "死亡时镜头拉远多少。"
L["How far the camera rises to look down on your body."] = "镜头升高多少来俯视你的尸体。"
L["The groups ticked here stay up while the death camera hides your frames."] = "死亡镜头隐藏你的框体时，这里勾选的分组保持显示。"
L["Music file IDs, separated by commas; one plays at random when you die."] = "音乐文件ID，用逗号分隔；死亡时随机播放其中一首。"
L["The camera turns toward NPCs as they talk near you."] = "NPC在你附近说话时镜头会转向他们。"
L["The fastest the camera swings toward a new speaker."] = "镜头转向新说话者的最快速度。"
L["How far from the screen's center the speaker ends up."] = "说话者最终离屏幕中央多远。"
L["How far the camera drifts side to side once settled."] = "镜头就位后左右漂移的幅度。"
L["The camera turns around to find speakers you can't see."] = "镜头会转过来寻找你看不到的说话者。"
L["Snaps to speakers, adds a tall letterbox with subtitles and fades the whole UI."] = "立即对准说话者，添加带字幕的宽黑边并淡出整个界面。"
L["How fast the camera zooms back out once the talking is over."] = "对话结束后镜头拉回的速度。"
L["The longest a zoom in or out can take."] = "一次拉近或拉远最长所需的时间。"
L["How long no one must talk before the camera turns back."] = "没人说话多久后镜头转回。"
L["When you talk to a quest giver, the camera zooms in and looks past you at them."] = "与任务NPC对话时，镜头会拉近并越过你看向他们。"
L["Also zooms in for NPCs with nothing to say about quests."] = "对没有任务可谈的NPC也会拉近。"
L["The camera stays put when a quest giver only has dailies or weeklies."] = "任务NPC只有日常或周常任务时镜头保持不动。"
L["How far the camera turns to one side to look past you."] = "镜头向一侧转多少来越过你看。"
L["How long the turn to the side takes."] = "转向一侧所需的时间。"
L["How fast the camera zooms back out once you walk away."] = "你走开后镜头拉回的速度。"
L["How far the camera comes down toward eye level."] = "镜头向视线高度降低多少。"
L["When you cast your Hearthstone or a teleport, the camera spins around you as it zooms in."] = "你使用炉石或传送时，镜头会边拉近边绕你旋转。"
L["The distance the zoom ends at as the cast finishes."] = "施法完成时缩放结束的距离。"
L["Canceling"] = "取消时"
L["If you cancel the cast, the camera turns back to where it was."] = "如果你取消施法，镜头会转回原来的位置。"
L["Extra settings for cameras that aren't on the Scripts page yet."] = "尚未移到脚本页面的镜头的额外设置。"
L["Mouse Turn"] = "鼠标转向"
L["Keeps right-mouse turning smooth by capping and easing its speed."] = "通过限制和缓和速度，让右键转向保持平滑。"
L["Cap"] = "上限"
L["Cap right-click turn speed"] = "限制右键转向速度"
L["Right-click turning never goes faster than the speed below."] = "右键转向永远不会超过下方的速度。"
L["Top turn speed"] = "最高转向速度"
L["The fastest you can turn."] = "你能转向的最快速度。"
L["Ease back over"] = "恢复耗时"
L["How long your own Mouse Look Speed takes to come back after you slow down."] = "减速后你自己的鼠标观察速度恢复所需的时间。"
L["Ramp up right-click turn speed"] = "逐渐提高右键转向速度"
L["Each right-click turn starts slow and builds up to your own speed."] = "每次右键转向都从慢开始，逐渐加快到你自己的速度。"
L["Start at"] = "起始于"
L["%d%% of your speed"] = "你速度的%d%%"
L["How fast a turn starts, as a share of your own Mouse Look Speed."] = "转向起始速度，占你自己鼠标观察速度的比例。"
L["Up to full speed over"] = "加速到全速耗时"
L["How long a turn takes to build up to full speed."] = "转向加速到全速所需的时间。"
L["Slow looking up and down too"] = "上下观察也减速"
L["Looking up and down slows by the same share as turning."] = "上下观察按与转向相同的比例减速。"
L["Turns the whole Atmosphere hub on or off at once."] = "一次开启或关闭整个氛围中心。"
L["How the game world looks in CineMode: vignette, inn glow, weather and depth of field."] = "游戏世界在CineMode中的外观：暗角、旅店光晕、天气和景深。"
L["Pick where and when each effect shows in CineMode."] = "选择每种效果在CineMode中何时何地显示。"
L["Shows all the time in CineMode, fights included."] = "在CineMode中一直显示，包括战斗中。"
L["Rain, snow and sandstorms tint the scene, more strongly in heavier weather."] = "雨、雪和沙尘暴会为画面染色，天气越恶劣越明显。"
L["Reduce view distance in bad weather"] = "恶劣天气时降低视野距离"
L["Brings the view distance in during rain, snow or sandstorms, more the heavier it gets."] = "下雨、下雪或沙尘暴时缩短视野距离，天气越恶劣缩得越多。"
L["The game's graphics settings one by one, shared by every profile on this computer."] = "逐项设置游戏的图形选项，由这台电脑上的所有配置文件共用。"
L["Uses the settings below, or the game's own when turned off."] = "使用下方的设置，关闭时使用游戏自带的设置。"
L["World"] = "世界"
L["Ground clutter, view distance, detail and shadows."] = "地面杂物、视野距离、细节和阴影。"
L["Sky and water"] = "天空和水面"
L["Clouds, fog, reflections and ripples."] = "云、雾、反射和波纹。"
L["Effects"] = "效果"
L["Particles, glow, blood and sharpening."] = "粒子、光晕、血液和锐化。"
L["HDR"] = "HDR"
L["HDR output and brightness."] = "HDR输出和亮度。"
L["Nameplate distance and zoom distance."] = "姓名板距离和镜头缩放距离。"
L["How far away grass and flowers start thinning out."] = "草和花从多远开始变稀疏。"
L["How far the land is drawn in full; very demanding on frame rate."] = "地形完整绘制的距离；非常影响帧数。"
L["How far away trees, rocks and other objects keep their full detail."] = "树木、岩石和其他物体在多远内保持完整细节。"
L["How far away small objects stay before they fade out."] = "小物体在多远之外淡出。"
L["How far away creatures and characters keep their full detail."] = "生物和角色在多远内保持完整细节。"
L["How far away nameplates show, in yards."] = "姓名板显示的距离，单位为码。"
L["How far out you can zoom the camera."] = "镜头最远能拉多远。"
L["Higher gives sharper shadow edges, lower saves frame rate."] = "越高阴影边缘越锐利，越低越节省帧数。"
L["Horizon distance"] = "地平线距离"
L["How far the flat horizon past the land reaches."] = "地形之外平坦地平线的延伸距离。"
L["Sky detail"] = "天空细节"
L["How detailed the clouds and sky are."] = "云和天空的细节程度。"
L["Volumetric fog"] = "体积雾"
L["Fog with depth in place of the usual distance fog."] = "用有纵深感的雾代替通常的距离雾。"
L["Water reflections"] = "水面反射"
L["How much of the world water reflects."] = "水面反射多少世界景物。"
L["Water ripples"] = "水面波纹"
L["How detailed the ripples on water are."] = "水面波纹的细节程度。"
L["Particle density"] = "粒子密度"
L["How many particles spells and effects show."] = "法术和效果显示多少粒子。"
L["Full-screen glow"] = "全屏泛光"
L["A soft glow around bright light."] = "明亮光源周围的柔和光晕。"
L["Gray screen on death"] = "死亡时灰屏"
L["The world turns gray while you're dead."] = "死亡时世界变为灰色。"
L["Blood and gore"] = "血腥效果"
L["How much blood shows in fights, from none to the most."] = "战斗中显示多少血液，从无到最多。"
L["Always sharpen"] = "始终锐化"
L["Sharpens the picture even at full render scale."] = "即使渲染比例为100%也锐化画面。"
L["HDR output"] = "HDR输出"
L["Sends HDR to your monitor; Windows HDR must be on and Auto HDR off."] = "向显示器输出HDR；必须开启Windows HDR并关闭自动HDR。"
L["Use peak brightness"] = "使用峰值亮度"
L["Peak brightness"] = "峰值亮度"
L["Your monitor's peak brightness, in nits."] = "你显示器的峰值亮度，单位为尼特。"
L["HDR strength"] = "HDR强度"
L["How strong HDR is; works with peak brightness only."] = "HDR的强度；仅配合峰值亮度使用。"
L["Use reference brightness"] = "使用参考亮度"
L["Reference brightness"] = "参考亮度"
L["How bright white looks in HDR, in nits."] = "HDR中白色的亮度，单位为尼特。"
L["Sky and weather"] = "天空和天气"
L["Water"] = "水面"
L["Restart graphics"] = "重启图形"
L["Restarts the game's graphics without leaving the game; the screen goes black for a moment."] = "无需退出游戏即可重启游戏图形；屏幕会短暂变黑。"
L["Sound and music during CineMode; your own sound settings come back afterward."] = "CineMode期间的声音和音乐；之后会恢复你自己的声音设置。"
L["Plays music when a camera starts in CineMode and fades it out when the UI returns."] = "在CineMode中镜头启动时播放音乐，界面回来时淡出音乐。"
L["Pick where and when music can play in CineMode."] = "选择在CineMode中何时何地可以播放音乐。"
L["After a camera starts music, no camera starts it again for this long."] = "某个镜头启动音乐后，在这段时间内不会有镜头再次启动音乐。"
L["Fades music out once you leave the camera modes and move on."] = "你离开镜头模式并继续行动后淡出音乐。"
L["Each row is a scene that plays its camera when one of its triggers happens."] = "每一行都是一个场景，在其某个触发器发生时播放其镜头。"
L["Lets the scenes below play their cameras when their triggers happen."] = "让下方的场景在其触发器发生时播放各自的镜头。"
L["Auto-running in walk mode."] = "以行走模式自动奔跑。"
L["Auto-running."] = "自动奔跑。"
L["Dying, until you release or are resurrected."] = "死亡，直到你释放灵魂或被复活。"
L["An NPC talking to you or your party; the camera swings toward whoever's talking."] = "NPC在与你或你的小队说话；镜头转向正在说话的人。"
L["Other NPCs talking near you, once you've stood still a while."] = "你站着不动一段时间后，附近有其他NPC在说话。"
L["Starts music as this camera starts; needs the Audio page on."] = "此镜头启动时开始播放音乐；需要开启音频页面。"
L["Plays a song of its own while the death camera runs."] = "死亡镜头运行时播放专属歌曲。"
L["Brings CineMode on while this camera runs, when Start in CineMode is off."] = "“以CineMode启动”关闭时，在此镜头运行期间开启CineMode。"
L["Buff names or spell IDs, separated by commas."] = "增益效果名称或法术ID，用逗号分隔。"
L["Words in an object's name that mark it as a seat, separated by commas."] = "物体名称中用于识别座位的词，用逗号分隔。"
L["How long you stand still before this row's camera starts."] = "你站着不动多久后此行的镜头启动。"
L["How long the camera waits on a quest window before it starts."] = "任务窗口打开后镜头等待多久再启动。"
L["How long the camera waits on the window before it starts."] = "窗口打开后镜头等待多久再启动。"
L["How long you stand still before NPCs chatting nearby start this camera."] = "你站着不动多久后，附近NPC的闲聊会启动此镜头。"
L["How long you keep going before this row's camera starts."] = "你持续多久后此行的镜头启动。"
L["Whether this row's camera may start in or after a fight."] = "此行的镜头是否可以在战斗中或战斗后启动。"
L["Where this row's camera may start."] = "此行的镜头可以在哪里启动。"
L["Pause cameras while a window is open"] = "窗口打开时暂停镜头"
L["Scenes pause while a window like the map or spellbook is open."] = "打开地图或法术书等窗口时场景暂停。"
L["Lists the rows by camera name or by scene name."] = "按镜头名称或场景名称列出各行。"
L["Make a scene of your own with its triggers, camera and end."] = "制作你自己的场景，设置其触发器、镜头和结束条件。"
L["A scene of your own; open it to set its triggers and when it ends."] = "你自己的场景；打开它可设置其触发器和结束时机。"
L["Copies this row just below, so you can give it another camera."] = "在下方复制此行，以便给它换一个镜头。"
L["Deletes this scene so it starts no camera."] = "删除此场景，使其不再启动任何镜头。"
L["Your own name for this row, shown on the grid."] = "你为此行起的名字，显示在表格中。"
L["The camera this row starts."] = "此行启动的镜头。"
L["This row's camera may start anywhere."] = "此行的镜头可以在任何地方启动。"
L["Indoors, the camera modes zoom out and swing less so they don't hit walls."] = "在室内，镜头模式拉远和摆动的幅度更小，以免撞到墙壁。"
L["How far past your own distance the slow zoom may pull back indoors."] = "在室内，慢速缩放最多可以比你自己的距离再拉远多少。"
L["Stops the AFK camera sweeping around you indoors, where it can hit walls."] = "在室内阻止暂离镜头环绕你，因为它可能撞到墙壁。"
L["Shows it whenever its frame shows, hovered or not."] = "只要其框体显示就显示它，无论是否悬停。"
L["Shows it the whole time, CineMode or not."] = "一直显示它，无论是否处于CineMode。"
L["CineMode hides everything: pick which frames show, and when."] = "CineMode会隐藏一切：选择哪些框体显示以及何时显示。"
L["CineMode hides everything: tick which frames show, and when."] = "CineMode会隐藏一切：勾选哪些框体显示以及何时显示。"
L["CineMode hides these frames, and shows them only when their rows say."] = "CineMode会隐藏这些框体，只在其行设置的情况下显示。"
L["CineMode hides the frames in this section, and shows them only when their rows say."] = "CineMode会隐藏此部分的框体，只在其行设置的情况下显示。"
L["Not in use"] = "未使用"
L["Shows or hides its parts."] = "显示或隐藏其各部分。"
L["Shows the same parts as the Target rows."] = "显示与目标行相同的部分。"
L["Raid-style party frames follow the Raid tab's rows."] = "团队风格的小队框体按团队标签页的行设置。"
L["Same as"] = "与此相同"
L["raid frames"] = "团队框架"
L["Opens the Raid tab."] = "打开团队标签页。"
L["Your Edit Mode layout has Use Raid-Style Party Frames ticked."] = "你的编辑模式布局已勾选“使用团队风格的小队框体”。"
L["Your Edit Mode layout has Use Raid-Style Party Frames unticked."] = "你的编辑模式布局未勾选“使用团队风格的小队框体”。"
L["Hide keybinds"] = "隐藏按键绑定"
L["Hides the key names on the action bar buttons (1, a-Q, s-2...), CineMode or not."] = "隐藏动作条按钮上的按键名称（1、a-Q、s-2……），无论是否处于CineMode。"
L["Hide macro names"] = "隐藏宏名称"
L["Hides the macro names on the action bar buttons, CineMode or not."] = "隐藏动作条按钮上的宏名称，无论是否处于CineMode。"
L["Show while the spellbook is open"] = "法术书打开时显示"
L["Keeps your action bars up while the spellbook or macros window is open."] = "法术书或宏窗口打开时让动作条保持显示。"
L["PRD"] = "个人资源"
L["Timers"] = "计时器"
L["Highlight"] = "高亮"
L["CineMode hides the unit frames: pick which show, and when."] = "CineMode会隐藏单位框体：选择哪些显示以及何时显示。"
L["CineMode hides your personal resource display: pick which parts show, and when."] = "CineMode会隐藏个人资源显示：选择哪些部分显示以及何时显示。"
L["CineMode hides your cast bar: pick when it shows."] = "CineMode会隐藏施法条：选择何时显示。"
L["CineMode hides the action bars: pick which show, and when."] = "CineMode会隐藏动作条：选择哪些显示以及何时显示。"
L["CineMode hides your buffs and debuffs: pick when they show."] = "CineMode会隐藏增益和减益效果：选择何时显示。"
L["CineMode hides timers and meters: pick which show, and when."] = "CineMode会隐藏计时器和统计：选择哪些显示以及何时显示。"
