L["CineMode hides the party frames: pick when they show."] = "CineMode会隐藏小队框体：选择何时显示。"
L["CineMode hides the raid frames: pick when they show."] = "CineMode会隐藏团队框架：选择何时显示。"
L["CineMode hides the raid-style party frames: pick when they show."] = "CineMode会隐藏团队风格的小队框体：选择何时显示。"
L["CineMode hides your character's highlight: pick when it shows."] = "CineMode会隐藏你角色的高亮：选择何时显示。"
L["CineMode hides these frames: pick which show, and when."] = "CineMode会隐藏这些框体：选择哪些显示以及何时显示。"
L["Pick where chat bubbles show."] = "选择聊天气泡在哪里显示。"
L["Pick where and when each kind of bubble shows."] = "选择每种气泡何时何地显示。"
L["These bubbles show everywhere, in fights and out."] = "这些气泡在任何地方都显示，无论是否在战斗中。"
L["Cinematic draws its own bubbles for speech whose game bubble you can't see."] = "对于你看不到游戏气泡的话语，Cinematic会绘制自己的气泡。"
L["Shows speech from someone off screen in a bubble low on the screen."] = "把屏幕外某人的话语显示在屏幕下方的气泡中。"
L["Opens the Chat Bubble Style page: how off-screen bubbles look and where they show."] = "打开聊天气泡风格页面：屏幕外气泡的外观和显示位置。"
