L["Adds a talent calculator button to your talents window to plan a build."] = "在天赋窗口中添加天赋模拟器按钮，用于规划天赋。"
L["Moves game windows away from the left edge so your character stays in view."] = "把游戏窗口从左边缘移开，让你的角色保持在视野中。"
