L["Turns the Hunter helpers on or off."] = "开启或关闭猎人辅助功能。"
L["Right-clicking an enemy uses Auto Shot when it's far enough away."] = "敌人距离足够远时，右键点击它会使用自动射击。"
L["Moves the smallest ammo stack first after Clean Up Bags, so it's shot first."] = "整理背包后把最小的弹药堆叠移到最前，让它先被射出。"
